  {
   "@type": "Question",
   "name": "If a product is vegan, was it not tested on animals?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Not necessarily. Vegan means no animal-derived ingredients; animal testing is a separate question. Some vegan certifications, like the Korea Agency of Vegan Certification, do also require no animal testing."
   }
  },
  {
   "@type": "Question",
   "name": "Can I trust PETA's cruelty-free list?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Companies and their ingredient suppliers sign a statement that they don't test on animals. It's less strict than Leaping Bunny, which adds supply-chain monitoring and audits, but stronger than a brand's own claim."
   }
  },
  {
   "@type": "Question",
   "name": "Doesn't Korea ban animal testing for cosmetics?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Since 2017 Korea's Cosmetics Act bans selling cosmetics tested on animals, with exceptions such as when an export country requires it. Household goods like detergent, toothpaste and pads are not cosmetics, so the ban doesn't cover them."
   }
  },
  {
   "@type": "Question",
   "name": "A brand isn't on PETA's list. Does it test on animals?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Not necessarily. Since August 2025 PETA only accepts new companies from the US, Canada, Germany and India, so newer Korean household brands can't easily join. Check other certifications or the brand's official policy."
   }
  }
 ]
